mapper.select:
SELECT user.id as userId, user.username, user.password, user.status, user.dept_id, role.code FROM sys_user `user` LEFT JOIN sys_user_role user_role ON user_role.user_id = `user`.id LEFT JOIN sys_role role ON role.id = user_role.role_id
user.deleted = 0 AND user.status = 1 AND role.status = 1
AND user.id = #{userId}
AND user.username = #{username}
AND user.email = #{email}
AND user.phoneNumber = #{phoneNumber}
AND user.id = -1

SELECT user.id, user.username, user.nickname, user.phone_number, user.gender, user.email, user.avatar, user.STATUS, dept.NAME AS dept_name, GROUP_CONCAT( role.NAME ) AS role_names, user.create_time FROM sys_user user LEFT JOIN sys_dept dept ON user.dept_id = dept.id LEFT JOIN sys_user_role user_role ON user.id = user_role.user_id LEFT JOIN sys_role role ON user_role.role_id = role.id
user.deleted = 0
AND ( user.username LIKE CONCAT('%',#{queryParams.keywords},'%') OR user.nickname LIKE CONCAT('%',#{queryParams.keywords},'%') OR user.phone_number LIKE CONCAT('%',#{queryParams.keywords},'%') OR user.email LIKE CONCAT('%',#{queryParams.keywords},'%') )
AND user.status = #{queryParams.status}
AND concat(',',concat(dept.tree_path,',',dept.id),',') like concat('%,',#{queryParams.deptId},',%')
AND user.create_time >= #{queryParams.startTime}
AND user.create_time <= #{queryParams.endTime}
GROUP BY user.id ORDER BY create_time DESC
